  if (options.text) text = String(options.text).trim();
  else if (options.message) text = String(options.message).trim();
}
if (!text && typeof message === "string" && message) {
  var m = message.trim();
  if (m !== "/handle_admin_input" && m !== "handle_admin_input") {
    text = m;
  }
}

